package college.ems.servlet;
import college.ems.dao.RegistryDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet(urlPatterns={"/businesses/*","/employees/*","/investments/*"}) public class RegistryServlet extends HttpServlet{
 private final RegistryDAO dao=new RegistryDAO();private String kind(HttpServletRequest r){return r.getServletPath().substring(1);}private String title(String k){return Character.toUpperCase(k.charAt(0))+k.substring(1);}
 @Override protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String k=kind(req),action=req.getPathInfo()==null?"/":req.getPathInfo();try{req.setAttribute("kind",k);req.setAttribute("title",title(k));req.setAttribute("records",dao.list(k));if("/new".equals(action)||"/edit".equals(action)){int id="/edit".equals(action)?Integer.parseInt(req.getParameter("id")):0;req.setAttribute("record",id==0?new HashMap<>():dao.find(k,id));req.setAttribute("parents",dao.parents(k));req.getRequestDispatcher("/WEB-INF/views/registry-form.jsp").forward(req,resp);return;}req.getRequestDispatcher("/WEB-INF/views/registry.jsp").forward(req,resp);}catch(Exception e){getServletContext().log("Registry page failed",e);req.setAttribute("kind",k);req.setAttribute("title",title(k));req.setAttribute("error","Could not load records. Check the database connection.");req.setAttribute("records",List.of());req.getRequestDispatcher("/WEB-INF/views/registry.jsp").forward(req,resp);}}
 @Override protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");String k=kind(req),action=req.getPathInfo()==null?"/":req.getPathInfo(),base=req.getContextPath()+"/"+k;try{if("/delete".equals(action)){dao.delete(k,Integer.parseInt(req.getParameter("id")));req.getSession().setAttribute("notice",title(k)+" record deleted.");resp.sendRedirect(base);return;}Map<String,String> v=new HashMap<>();for(String key:List.of("parentId","name","type","industry","description","date","location","status","email","phone","amount"))v.put(key,Objects.toString(req.getParameter(key),"").trim());if(v.get("name").isBlank()||v.get("parentId").isBlank())throw new IllegalArgumentException("Please enter a name and select the related record.");if("employees".equals(k)&&!v.get("email").isBlank()&&!v.get("email").matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Enter a valid employee email address.");if("investments".equals(k)){try{if(new java.math.BigDecimal(v.get("amount")).signum()<=0)throw new IllegalArgumentException("Investment amount must be greater than zero.");}catch(NumberFormatException ex){throw new IllegalArgumentException("Enter a valid investment amount.");}}if(!v.get("date").isBlank())try{java.time.LocalDate.parse(v.get("date"));}catch(java.time.format.DateTimeParseException ex){throw new IllegalArgumentException("Enter a valid date.");}Integer id=req.getParameter("id")==null||req.getParameter("id").isBlank()?null:Integer.valueOf(req.getParameter("id"));dao.save(k,id,v);req.getSession().setAttribute("notice",title(k)+(id==null?" record added.":" record updated."));resp.sendRedirect(base);}catch(Exception e){getServletContext().log("Registry save failed",e);req.setAttribute("kind",k);req.setAttribute("title",title(k));Map<String,String> old=new HashMap<>();req.getParameterMap().forEach((key,val)->{if(val.length>0)old.put(key,val[0]);});req.setAttribute("record",old);try{req.setAttribute("parents",dao.parents(k));}catch(Exception ignored){}String msg=e instanceof IllegalArgumentException&&e.getMessage()!=null&&(e.getMessage().startsWith("Please")||e.getMessage().startsWith("Enter")||e.getMessage().startsWith("Investment"))?e.getMessage():"Could not save this record. Verify the fields and database connection.";req.setAttribute("error",msg);req.getRequestDispatcher("/WEB-INF/views/registry-form.jsp").forward(req,resp);}}
}
